report=dict(status='Pass',blurred_depth_draft_retained_through_real_layer_hide_show=True,applied_dimensions_mm=[20,10,30],volume_mm3=volume,independent_wedge_vertex_set=True,other_source_and_paint_fields_exact=True,hashes=hashes,notes='Original wrong-depth native attempt is not attributed solely to the product: initial native-key helper did not reliably enter10. Deterministic four-layout red/green proves the background-refresh reset; scoped live field entry and real layer refreshes verify the repair.');(out/'solid170-verification.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
